UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Perimortem C-Section Decision","body":"**Is the patient in cardiac arrest AND at ≥20 weeks gestation (or fundus ≥ umbilicus)?**\n\n**The 4-Minute Rule (AHA 2025):** if ROSC not achieved by 4 minutes of arrest, **start resuscitative hysterotomy at minute 4 — deliver by minute 5.** The 4-minute mark is a *prompt to act*, not a rigid deadline — hysterotomy still benefits maternal resuscitation beyond that window, and earlier delivery-from-arrest = better outcomes. Prepare at the moment of arrest. [7][8][9]\n\n**Why it works:**\n• Relieves aortocaval compression → improves maternal venous return and CPR effectiveness\n• Cardiac output in pregnancy CPR is only ~30% of non-pregnant; emptying the uterus restores it\n• **The primary goal is maternal survival** — not fetal rescue\n\n**Where:** at bedside. Do NOT transport to OR.\n**How:** midline vertical skin + vertical uterine incision; no anesthesia (patient in arrest); continue CPR throughout.\n\n→ Full procedural walkthrough: **[Resuscitative Hysterotomy consult](#/tree/resuscitative-hysterotomy)**","citation":[7,8,9],"options":[{"label":"Arrest + ≥20 wk — perform hysterotomy","next":"afe-pmcd","urgency":"critical"},{"label":"Shock without arrest — continue resuscitation","description":"Defer hysterotomy unless deterioration","next":"afe-pharm-branch"},{"label":"<20 wk or no fundus palpable","description":"Hysterotomy not indicated — standard adult ACLS","next":"afe-pharm-branch"}],"summary":"4-min rule (AHA 2025): arrest + ≥20 wk = start hysterotomy, deliver by 5 min — at bedside; 4-min is a prompt, benefit extends beyond","safetyLevel":"critical"}'::jsonb
WHERE id = 'afe-pmcd-decision' AND tree_id = 'afe';

-- Node: afe-pharm-branch (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Pharmacologic Adjuncts — A-O-K","body":"**A-O-K protocol** (Rezai 2017) — proposed to block three pulmonary vasoconstriction/platelet pathways simultaneously.\n\n**⚠️ NOT recommended as of 2025.** Pacheco et al. (Obstet Gynecol 2025;147:780-784) reviewed the evidence — case reports only — and **cautions AGAINST A-O-K** for suspected AFE, citing potential harms: worsening coagulopathy/bleeding (ketorolac antiplatelet effect in a DIC-prone patient), kidney injury, and cardiac complications. AWHONN 2025 concurs: no proposed pharmacologic therapy is evidence-supported.\n\n**Mainstay remains supportive:** high-quality CPR, oxygenation, BP support, RV/heart-failure management, and coagulopathy correction.\n\nIf A-O-K is used at all (individual clinician judgment in a refractory case), the originally described doses are **Atropine 1 mg + Ondansetron 8 mg + Ketorolac 30 mg IV** — do NOT let it delay or substitute for ACLS, MTP, pressors, or hysterotomy. [4][13]\n\n**Alternative: \"50-50-500\"** (older anaphylactoid hypothesis, equally low evidence):\n• [Diphenhydramine](#/drug/diphenhydramine/amniotic fluid embolism) 50 mg IV\n• [Famotidine](#/drug/famotidine/amniotic fluid embolism) 50 mg IV (or 20 mg — hospital formulary)\n• [Hydrocortisone](#/drug/hydrocortisone/amniotic fluid embolism) 500 mg IV\n\n**These are adjuncts — do not substitute for ACLS, MTP, pressors, or hysterotomy.**","citation":[4,13],"next":"afe-hemo","summary":"A-O-K NOT recommended (Pacheco 2025, case-reports only, harm risk) — mainstay is supportive: CPR, O2, BP, RV support, coagulopathy correction"}'::jsonb
